import { HttpClient } from '@angular/common/http';
import { Component, inject, OnInit, signal } from '@angular/core';
import { ActivatedRoute } from '@angular/router';

@Component({
  selector: 'app-user-page',
  template: `<h1>{{ user()?.name }}</h1>`,
})
export class UserPage implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly http = inject(HttpClient);
  readonly user = signal<User | undefined>(undefined);

  ngOnInit() {
    // Runs once per instance: /users/1 → /users/2 keeps user 1
    const id = this.route.snapshot.paramMap.get('id');
    this.http
      .get<User>(`/api/users/${id}`)
      .subscribe((u) => this.user.set(u));
  }
}

import { httpResource } from '@angular/common/http';
import { Component, input } from '@angular/core';

@Component({
  selector: 'app-user-page',
  template: `
    @if (user.hasValue()) {
      <h1>{{ user.value().name }}</h1>
    }
  `,
})
export class UserPage {
  // Bound from :id, and updated when only the param changes
  readonly id = input.required<string>();
  // A new request each time id changes; a pending one is cancelled
  readonly user = httpResource<User>(() => `/api/users/${this.id()}`);
}
